const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解：设未知数为 x' },
      { kind: 'text', payload: '由题意列方程' },
      { kind: 'text', payload: '移项得' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var W = (typeof vp.widthDu === 'number' && vp.widthDu > 0) ? vp.widthDu : 480;
    var H = (typeof vp.heightDu === 'number' && vp.heightDu > 0) ? vp.heightDu : 320;
    var texts = ['解：设未知数为 x', '由题意列方程', '移项得'];
    var measures = [];
    var i, k, e, w, h, approx, ch, fb;
    for (i = 0; i < texts.length; i += 1) {
      e = (metrics && metrics[i]) ? metrics[i] : null;
      w = null;
      h = null;
      if (e) {
        if (typeof e.width === 'number' && e.width > 0) { w = e.width; }
        else if (typeof e.w === 'number' && e.w > 0) { w = e.w; }
        if (typeof e.height === 'number' && e.height > 0) { h = e.height; }
        else if (typeof e.h === 'number' && e.h > 0) { h = e.h; }
      }
      fb = Math.max(14, Math.min(26, W * 0.055));
      if (h === null) { h = fb; }
      if (w === null) {
        approx = 0;
        for (k = 0; k < texts[i].length; k += 1) {
          ch = texts[i].charAt(k);
          approx += (ch.charCodeAt(0) > 255) ? 1 : 0.55;
        }
        w = approx * fb * 0.95;
      }
      measures.push({ w: w, h: h });
    }
    var pad = Math.max(10, Math.round(Math.min(W, H) * 0.06));
    var pageX = pad;
    var pageY = pad;
    var pageW = Math.max(80, W - pad * 2);
    var pageH = Math.max(80, H - pad * 2);
    var innerPadX = Math.max(12, Math.round(pageW * 0.07));
    var innerPadY = Math.max(14, Math.round(pageH * 0.10));
    var innerX = pageX + innerPadX;
    var innerTop = pageY + innerPadY;
    var totalH = 0;
    for (i = 0; i < measures.length; i += 1) { totalH += measures[i].h; }
    var gap = Math.max(6, Math.round(measures[0].h * 0.75));
    var usable = pageH - innerPadY * 2;
    var need = totalH + gap * (measures.length - 1);
    if (need > usable && measures.length > 1) {
      gap = Math.max(2, Math.floor((usable - totalH) / (measures.length - 1)));
    }
    var page = visualSdk.polyline([
      [pageX, pageY],
      [pageX + pageW, pageY],
      [pageX + pageW, pageY + pageH],
      [pageX, pageY + pageH],
      [pageX, pageY]
    ]);
    var children = [
      { type: 'path', pathId: 'page', fill: '#ffffff', stroke: { width: 1.5 } }
    ];
    var cy = innerTop;
    for (i = 0; i < texts.length; i += 1) {
      children.push({
        type: 'label',
        contentId: 'c' + i,
        anchor: { x: innerX, y: cy },
        hAlign: 'left',
        vAlign: 'top',
        color: '#1f2933'
      });
      cy += measures[i].h + gap;
    }
    return {
      schemaVersion: 1,
      sceneId: 'printed-solution-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'page', commands: page }],
      root: { type: 'group', children: children }
    };
  }
};
